                el.style.position = 'absolute';
                el.style.right = 'auto'; el.style.bottom = 'auto';
                el.style.width = (w / guiScale) + 'px'; el.style.height = (h / guiScale) + 'px';
                el.style.left = (sx / guiScale) + 'px'; el.style.top = (sy / guiScale) + 'px';
